@@ -62,1 +62,11 @@
-        TestFramework.runWithFlags(args);
+        switch(args[0]) {
+            case "vanilla" -> {
+                TestFramework.run();
+            }
+            case "noWarmup" -> {
+                TestFramework f = new TestFramework();
+                f.setDefaultWarmup(0);
+                f.addFlags("-XX:-TieredCompilation", "-XX:CompileCommand=compileonly,${test.main.class}::test*");
+                f.start();
+            }
+        }
